atualizados as (
  update public.clients c
     set won_at = g.won_at
    from ganhos g
   where c.id_hubspot = g.id_hubspot
     and c.won_at is null
  returning c.id
)
select
  (select count(*) from ganhos)                          as ganhos_no_hubspot,
  (select count(*) from atualizados)                     as carimbados,
  (select count(*) from ganhos g
     where not exists (select 1 from public.clients c
                        where c.id_hubspot = g.id_hubspot)) as sem_pin_no_app,
  (select count(*) from public.clients where won_at is not null) as total_com_data_no_fim;
